import json
from enum import Enum
from typing import Any
from typing import Dict
from typing import Literal
from typing import Optional
from typing import Union

from pydantic import BaseModel
from pydantic import ConfigDict
from pydantic import Field

from commons.enums import AgentType
from commons.monitoring import logging


logger = logging.get_logger(__name__)


class CallKind(str, Enum):
    WEB = "web"
    PLAYGROUND = "playground"
    OUTBOUND = "outbound"
    INBOUND = "inbound"


class BaseRoomMetadata(BaseModel):
    model_config = ConfigDict(validate_by_name=True, validate_by_alias=True)

    agent: Optional[AgentType] = Field(alias="agent", default=None)

    def to_json(self) -> str:
        """Convert metadata to JSON string"""
        return json.dumps(self.model_dump())

    @classmethod
    def from_json(cls, json_str: str) -> "BaseRoomMetadata":
        """Create metadata from JSON string"""
        data = json.loads(json_str)
        return cls(**data)

    def merge_with(self, other_data: Dict[str, Any]) -> Dict[str, Any]:
        """Merge this metadata with additional data"""
        result = self.model_dump()
        if other_data:
            # Only update non-empty values
            for key, value in other_data.items():
                if value is not None and value != "":
                    result[key] = value
        return result


class InboundRoomMetadata(BaseRoomMetadata):
    model_config = ConfigDict(validate_by_name=True, validate_by_alias=True)

    kind: Literal["inbound"] = Field(alias="kind", default="inbound")
    agent_phone_number: str = Field(alias="agentPhoneNumber")
    candidate_phone_number: str = Field(alias="candidatePhoneNumber")
    agent_trunk_id: str = Field(alias="agentTrunkId")
    engagement_id: Optional[str] = Field(alias="engagementId", default=None)


class WebRoomMetadata(BaseRoomMetadata):
    model_config = ConfigDict(validate_by_name=True, validate_by_alias=True)

    kind: Literal["web"] = Field(alias="kind", default="web")
    opportunity_id: str = Field(alias="opportunityId")
    sequence_item_id: Optional[str] = Field(alias="sequenceItemId", default=None)
    engagement_id: Optional[str] = Field(alias="engagementId", default=None)


class PlaygroundRoomMetadata(BaseRoomMetadata):
    model_config = ConfigDict(validate_by_name=True, validate_by_alias=True)

    kind: Literal["playground"] = Field(alias="kind", default="playground")
    opportunity_id: str = Field(alias="opportunityId")
    sequence_item_id: Optional[str] = Field(alias="sequenceItemId", default=None)
    engagement_id: Optional[str] = Field(alias="engagementId", default=None)


class OutboundRoomMetadata(BaseRoomMetadata):
    model_config = ConfigDict(validate_by_name=True, validate_by_alias=True)

    kind: Literal["outbound"] = Field(alias="kind", default="outbound")
    opportunity_id: str = Field(alias="opportunityId")
    sequence_item_id: Optional[str] = Field(alias="sequenceItemId", default=None)
    candidate_phone_number: str = Field(alias="candidatePhoneNumber")
    agent_trunk_id: str = Field(alias="agentTrunkId")
    engagement_id: Optional[str] = Field(alias="engagementId", default=None)


RoomMetadata = Union[
    InboundRoomMetadata, OutboundRoomMetadata, WebRoomMetadata, PlaygroundRoomMetadata
]


def parse_room_metadata(metadata_json: str) -> RoomMetadata:
    """Parse room metadata from JSON string"""
    try:
        data = json.loads(metadata_json)
        kind = data.get("kind", CallKind.WEB.value)

        if kind == CallKind.INBOUND.value:
            return InboundRoomMetadata(**data)
        elif kind == CallKind.OUTBOUND.value:
            return OutboundRoomMetadata(**data)
        elif kind == CallKind.PLAYGROUND.value:
            return PlaygroundRoomMetadata(**data)
        else:
            return WebRoomMetadata(**data)
    except (json.JSONDecodeError, ValueError):
        logger.warning(
            "Unable to parse room metadata. returning default", raw_data=metadata_json
        )
        return PlaygroundRoomMetadata(
            agent=AgentType.SCREENING,
            engagement_id=None,
            opportunity_id="",
        )
